create table xxcus.xxfnd_attached_documents (
    attached_document_id  number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    document_id           number not null enable,
    entity_name           varchar2(60 byte) not null enable,
    pk1_value             varchar2(150 byte) not null enable,
    pk2_value             varchar2(150 byte),
    pk3_value             varchar2(150 byte),
    pk4_value             varchar2(150 byte),
    pk5_value             varchar2(150 byte),
    category_code         varchar2(30 byte) not null enable,
    seq_num               number default 10 not null enable,
    primary_category_flag varchar2(1 byte) default 'N' not null enable,
    expiration_date       timestamp(6),
    attribute_category    varchar2(150 byte),
    attribute1            varchar2(150 byte),
    attribute2            varchar2(150 byte),
    attribute3            varchar2(150 byte),
    attribute4            varchar2(150 byte),
    attribute5            varchar2(150 byte),
    attribute6            varchar2(150 byte),
    attribute7            varchar2(150 byte),
    attribute8            varchar2(150 byte),
    attribute9            varchar2(150 byte),
    attribute10           varchar2(150 byte),
    attribute11           varchar2(150 byte),
    attribute12           varchar2(150 byte),
    attribute13           varchar2(150 byte),
    attribute14           varchar2(150 byte),
    attribute15           varchar2(150 byte),
    attribute16           varchar2(150 byte),
    attribute17           varchar2(150 byte),
    attribute18           varchar2(150 byte),
    attribute19           varchar2(150 byte),
    attribute20           varchar2(150 byte),
    attribute21           varchar2(150 byte),
    attribute22           varchar2(150 byte),
    attribute23           varchar2(150 byte),
    attribute24           varchar2(150 byte),
    attribute25           varchar2(150 byte),
    attribute26           varchar2(150 byte),
    attribute27           varchar2(150 byte),
    attribute28           varchar2(150 byte),
    attribute29           varchar2(150 byte),
    attribute30           varchar2(150 byte),
    attribute_number1     number,
    attribute_number2     number,
    attribute_number3     number,
    attribute_number4     number,
    attribute_number5     number,
    attribute_number6     number,
    attribute_number7     number,
    attribute_number8     number,
    attribute_number9     number,
    attribute_number10    number,
    attribute_date1       date,
    attribute_date2       date,
    attribute_date3       date,
    attribute_date4       date,
    attribute_date5       date,
    attribute_date6       date,
    attribute_date7       date,
    attribute_date8       date,
    attribute_date9       date,
    attribute_date10      date,
    attribute_timestamp1  timestamp(6),
    attribute_timestamp2  timestamp(6),
    attribute_timestamp3  timestamp(6),
    attribute_timestamp4  timestamp(6),
    attribute_timestamp5  timestamp(6),
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_attached_documents
    add constraint xxfnd_attached_documents_ck1
        check ( primary_category_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_attached_documents
    add constraint xxfnd_attached_documents_pk primary key ( attached_document_id )
        using index enable;


